			{"areaHotkey", "Area"},
			{"sightHotkey", "Line of sight"},
			{"colourHotkey", "Next colour"},
			{"groupHotkey", "Next group"},
			{"undoHotkey", "Undo"},
			{"redoHotkey", "Redo"},
