			case "areaHotkey":
				return config.areaHotkey();
			case "sightHotkey":
				return config.sightHotkey();
			case "colourHotkey":
				return config.colourHotkey();
			case "groupHotkey":
				return config.groupHotkey();
			case "undoHotkey":
				return config.undoHotkey();
